<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agency subscription | CareSys</title><link rel="stylesheet" href="/assets/caresys.css"></head><body><a class="skip" href="#main-content">Skip to content</a><div class="shell"><?= view('components/workspace_sidebar',['w'=>$w,'memberships'=>$memberships,'base'=>$base,'page'=>'billing']) ?><div class="main"><main id="main-content" class="content"><section class="card"><div class="standalone-notification-bar"><?= view('components/notification_menu',['w'=>$w]) ?></div><h1><?= $status['owner']?'Agency subscription & free trial':('Agency account') ?></h1><p><?= esc($agency['name']) ?></p>
<?php if(session('message')): ?><p class="alert" role="status"><?= esc(session('message')) ?></p><?php endif ?><?php if(session('error')): ?><p class="alert error" role="alert"><?= esc(session('error')) ?></p><?php endif ?>
<?php if(!$status['owner']): ?><p role="alert"><?= esc($status['notice']) ?></p><?php else: ?>
<p><strong>Status: <?= esc(str_replace('_',' ',$status['state'])) ?></strong></p><p><?= esc($status['notice']) ?></p>
<?php if($status['trial_ends_at']??null): ?><p>Free trial ends: <strong><?= esc($status['trial_ends_at']) ?> UTC</strong></p><?php endif ?>
<?php if($status['paid_until']??null): ?><p>Paid access ends: <strong><?= esc($status['paid_until']) ?> UTC</strong></p><?php endif ?>
<?php if($status['local_simulator']??false): ?><aside class="notice" role="status"><strong>Local billing test mode</strong><p>No real card is required and no money is collected. Use these controls to test module selection, invoices, trial expiry and owner payment approval. Test access works only while this local simulator is enabled.</p>
<?php $testActions=[];if(!($status['card_verified']??false))$testActions['test-setup']='Simulate card setup';if($status['state']==='trial' && ($status['simulated_billing']??false))$testActions['test-expire']='End test trial now';if($status['state']==='payment_required' && ($status['simulated_billing']??false) && ($status['invoice_ref']??null))$testActions['test-payment']='Approve simulated invoice payment';foreach($testActions as $testAction=>$label): ?>
<form method="post" action="<?= esc($base) ?>/billing/actions/<?= esc($testAction) ?>"><?= csrf_field() ?><input type="hidden" name="workspace_nonce" value="<?= esc($nonce,'attr') ?>"><input type="hidden" name="invoice_ref" value="<?= esc($status['invoice_ref']??'','attr') ?>"><label><input type="checkbox" name="confirm" value="yes" required> I confirm this local test action only.</label><p><button><?= esc($label) ?></button></p></form>
<?php endforeach ?></aside><?php elseif($status['simulated_billing']??false): ?><p class="notice">This account used simulated billing. Re-enable the local simulator to continue testing. Use a fresh agency for real Stripe billing.</p><?php endif ?>
<?php if(!($status['stripe_configured']??false) && !($status['local_simulator']??false)): ?><p class="notice">Secure card setup is awaiting Stripe configuration by the platform administrator. Trial activation and payment remain unavailable until configured.</p><?php endif ?>
<?php if(!($status['card_verified']??false)): ?><?php if(!($status['local_simulator']??false)): ?><h2>1. Save your card securely</h2><p>Your <?= (int)$status['trial_days'] ?>-day free trial begins once Stripe verifies your card and you select your modules. No subscription payment is deducted during the trial. After it ends, an owner must explicitly approve payment to unlock agency access. Your bank may display a temporary card verification authorization.</p><form method="post" action="<?= esc($base) ?>/billing/actions/setup"><?= csrf_field() ?><input type="hidden" name="workspace_nonce" value="<?= esc($nonce,'attr') ?>"><input type="hidden" name="request_key" value="<?= bin2hex(random_bytes(16)) ?>"><label><input type="checkbox" name="confirm" value="yes" required> I agree to save a card with Stripe and understand that later payment requires my approval.</label><p><button <?= !($status['stripe_configured']??false)?'disabled':'' ?>>Continue to secure card setup</button></p></form>
<?php endif ?><?php else: ?><p>Verified card: <?= esc($status['card_brand']??'Card') ?> ending <?= esc($status['card_last4']??'') ?></p><h2>Select modules and receive your invoice</h2><?php echo view('components/subscription_quote',compact('agency','base','nonce','subscription_invoices','active_worker_count')+['billing_action'=>$base.'/billing/actions/quote']); ?>
<?php if($status['state']==='payment_required' && !($status['simulated_billing']??false)): ?><h2>Trial or paid access has ended — approve payment to continue</h2><p>No automatic charge has been made. Review your current invoice and approve the amount on Stripe. Successful payment unlocks this agency for 30 days; renewal also requires approval.</p><?php $current=null;foreach($subscription_invoices as $item)if($item['ref']===($status['invoice_ref']??''))$current=$item; ?><?php if($current && $current['state']==='issued'): ?><p><?= esc($current['invoice_no']) ?> — USD <?= number_format($current['total_cents']/100,2) ?> before any applicable tax shown by Stripe</p><form method="post" action="<?= esc($base) ?>/billing/actions/payment"><?= csrf_field() ?><input type="hidden" name="workspace_nonce" value="<?= esc($nonce,'attr') ?>"><input type="hidden" name="request_key" value="<?= bin2hex(random_bytes(16)) ?>"><input type="hidden" name="invoice_ref" value="<?= esc($current['ref']) ?>"><label><input type="checkbox" name="confirm" value="yes" required> I approve proceeding to payment for this invoice. Stripe will show the final amount before I pay.</label><p><button <?= !($status['stripe_configured']??false)?'disabled':'' ?>>Approve payment on Stripe</button></p></form><?php else: ?><p>Choose your modules above to request a current invoice for the next 30 days.</p><?php endif;endif;endif ?>
<?php $key=service('request')->getGet('checkout_key');if(is_string($key)&&preg_match('/^[a-f0-9]{32}$/D',$key)):$checkout=$w->table('billing_checkouts')->where('request_key',$key)->get()->getRowArray();if($checkout): ?><h2>Verify your Stripe checkout</h2><form method="post" action="<?= esc($base) ?>/billing/actions/complete"><?= csrf_field() ?><input type="hidden" name="workspace_nonce" value="<?= esc($nonce,'attr') ?>"><input type="hidden" name="ref" value="<?= esc($checkout['ref']) ?>"><button>Verify completed checkout</button></form><?php endif;endif ?>
<?php if(!$status['locked']): ?><p><a href="<?= esc($base) ?>/dashboard">Continue to agency workspace →</a></p><?php endif;endif ?><p><a href="/app">Personal account</a></p><form method="post" action="/logout"><?= csrf_field() ?><button class="secondary">Sign out</button></form></section></main></div></div><script src="/assets/caresys.js" defer></script></body></html>
